contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address who) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        uint balBefore = address(c).balance;
        uint userBefore = c.getBalance(who); if (__ESBMC_reverted()) return;

        uint ret1 = c.getBalance(who); if (__ESBMC_reverted()) return;
        uint ret2 = c.getBalance(who); if (__ESBMC_reverted()) return;

        uint balAfter = address(c).balance;
        uint userAfter = c.getBalance(who); if (__ESBMC_reverted()) return;

        assert(balAfter == balBefore && userAfter == userBefore && ret1 == userBefore && ret2 == ret1);
    }

    receive() external payable {}
}

